package dao; import java.sql.*; import java.util.*; import negocio.*; public class ParticipanteComunidadDAOMySQL implements ParticipanteComunidadDAO { public void guardar(Connection c,ParticipanteComunidad v){v.validar();String q="INSERT INTO comunidad_participantes(convocatoria_id,perfil_jugador_id,tipo,estado,descripcion_publica,origen,fecha_confirmacion) VALUES(?,?,?,?,?,?,?)";try(PreparedStatement s=c.prepareStatement(q,Statement.RETURN_GENERATED_KEYS)){s.setLong(1,v.getConvocatoriaId());if(v.getPerfilJugadorId()==null)s.setNull(2,Types.BIGINT);else s.setLong(2,v.getPerfilJugadorId());s.setString(3,v.getTipo().name());s.setString(4,v.getEstado().name());s.setString(5,v.getDescripcionPublica());s.setString(6,v.getOrigen().name());if(v.getFechaConfirmacion()==null)s.setNull(7,Types.TIMESTAMP);else s.setTimestamp(7,Timestamp.valueOf(v.getFechaConfirmacion()));s.executeUpdate();try(ResultSet r=s.getGeneratedKeys()){if(r.next())v.setId(r.getLong(1));}}catch(SQLException e){throw e.getErrorCode()==1062?new IllegalArgumentException("El perfil ya participa en la convocatoria.",e):new RuntimeException("No se pudo guardar el participante.",e);}} public List<ParticipanteComunidad> listarPorConvocatoria(Connection c,long id,boolean lock){String q="SELECT * FROM comunidad_participantes WHERE convocatoria_id=? ORDER BY id"+(lock?" FOR UPDATE":"");try(PreparedStatement s=c.prepareStatement(q)){s.setLong(1,id);try(ResultSet r=s.executeQuery()){List<ParticipanteComunidad>o=new ArrayList<>();while(r.next()){ParticipanteComunidad v=new ParticipanteComunidad();v.setId(r.getLong("id"));v.setConvocatoriaId(r.getLong("convocatoria_id"));long p=r.getLong("perfil_jugador_id");v.setPerfilJugadorId(r.wasNull()?null:p);v.setTipo(TipoParticipanteComunidad.valueOf(r.getString("tipo")));v.setEstado(EstadoParticipanteComunidad.valueOf(r.getString("estado")));v.setDescripcionPublica(r.getString("descripcion_publica"));v.setOrigen(OrigenParticipanteComunidad.valueOf(r.getString("origen")));Timestamp t=r.getTimestamp("fecha_confirmacion");if(t!=null)v.setFechaConfirmacion(t.toLocalDateTime());o.add(v);}return o;}}catch(SQLException e){throw new RuntimeException("No se pudieron consultar los participantes.",e);}} public int contarConfirmados(Connection c,long id){try(PreparedStatement s=c.prepareStatement("SELECT COUNT(*) FROM comunidad_participantes WHERE convocatoria_id=? AND estado='CONFIRMADO'")){s.setLong(1,id);try(ResultSet r=s.executeQuery()){r.next();return r.getInt(1);}}catch(SQLException e){throw new RuntimeException("No se pudieron contar los participantes.",e);}}}
